import{_ as e,o as a,c as n,aa as i}from"./chunks/framework.BAs_AphD.js";const m=JSON.parse('{"title":"Novinky verze 4.7","description":"","frontmatter":{"title":"Novinky verze 4.7","wiki":"cs:news:vrsion_4.7"},"headers":[],"relativePath":"news/version_4-7.md","filePath":"news/version_4-7.md","lastUpdated":1793708206000}'),l={name:"news/version_4-7.md"};function t(r,o,d,s,v,k){return a(),n("div",null,[...o[0]||(o[0]=[i('<h1 id="novinky-verze-4-7" tabindex="-1">Novinky verze 4.7 <a class="header-anchor" href="#novinky-verze-4-7" aria-label="Permalink to &quot;Novinky verze 4.7&quot;">​</a></h1><p>Po kompletním předělání mobilní aplikace pro Android i iOS, kterou jsme o prázdninách vydali jako zbrusu novou aplikaci, neleníme a přicházíme s dalším balíčkem novinek v Buildary. Sami jste po nich volali, a tak věříme, že z těchto novinek budete mít radost 😃</p><ul><li>Platební QR kódy</li><li>Úprava obsahu e-mailových oznámení</li><li>Požární kniha</li><li>Export oficiální verze deníku - roztřídění příloh Dokumentů deníku</li><li>Vzorová stavba se vzorovými úkoly</li><li>Zjišťovací protokol s doplněnými údaji</li></ul><h2 id="platebni-qr-kody" tabindex="-1">Platební QR kódy <a class="header-anchor" href="#platebni-qr-kody" aria-label="Permalink to &quot;Platební QR kódy&quot;">​</a></h2><p>Jedna z těch zásadních změn, po kterých jste volali nejvíce. Máte rádi QR kódy pro zadávání plateb - a my se nedivíme. Navedení platby je rychlejší a bezchybné, a proto PDF Výzvy k platbě nově obsahují QR kód.<br> QR kódy jsou na CZK i EUR dokladech. Kompatibilní s téměř všemi českými a slovenskými bankami, pouze slovenská mBank má prozatím se čtením QR kódu problém.</p><h2 id="uprava-e-mailovych-oznameni" tabindex="-1">Úprava e-mailových oznámení <a class="header-anchor" href="#uprava-e-mailovych-oznameni" aria-label="Permalink to &quot;Úprava e-mailových oznámení&quot;">​</a></h2><p>Provedli jsme revizi našich e-mailových oznámení a u některých z nich lehce upravili obsah, např. o odkazy k dalším informacím, které by se uživateli mohly hodit.<br><br> Například <strong>Pozvánka do projektu</strong> (při vložení člena projektu do projektového týmu stavby) obsahuje QR kódy pro pohodlné stažení nové mobilní aplikace pro Android / iOS. Od října jsme totiž ukončili podporu původní aplikace a od října frčíme už jen na nové 😎</p><h2 id="modul-stavebni-denik" tabindex="-1">Modul STAVEBNÍ DENÍK <a class="header-anchor" href="#modul-stavebni-denik" aria-label="Permalink to &quot;Modul STAVEBNÍ DENÍK&quot;">​</a></h2><ul><li>Seznamu typů deníků jsme rozšířili o dosud chybějící <strong>Požární knihu</strong>. Sekce a popis položek pro záznamy zůstal v Požární knize zachován dle ostatních stavebních deníků.<br><br></li><li>Při <strong>exportu oficiální verze deníku</strong> budou přílohy v titulních listech deníku roztříděny do stejnojmenných složek, jako jsou podzáložky v části Dokumenty deníku, tj. Základní doklady / Projektová dokumentace / Kontroly a zkoušky / Ostatní dokumenty.</li></ul><h2 id="modul-management-ukolu" tabindex="-1">Modul MANAGEMENT ÚKOLŮ <a class="header-anchor" href="#modul-management-ukolu" aria-label="Permalink to &quot;Modul MANAGEMENT ÚKOLŮ&quot;">​</a></h2><ul><li><strong>Do vzorové stavby</strong> je nyní možné vkládat <strong>vzorové úkoly</strong>. Při založení stavby z tohoto vzoru se zkopírují i vzorové úkoly. A to včetně výkresů se značkami a příloh.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Vzorové úkoly ve vzorové stavbě jsou automaticky ve stavu Draft, který není možné editovat. Stejně tak nelze ke vzorovému úkolu vložit vyjádření nebo diskusi.</p></div><h2 id="modul-soupisy-provedenych-praci" tabindex="-1">Modul SOUPISY PROVEDENÝCH PRACÍ <a class="header-anchor" href="#modul-soupisy-provedenych-praci" aria-label="Permalink to &quot;Modul SOUPISY PROVEDENÝCH PRACÍ&quot;">​</a></h2><ul><li><strong>Ve zjišťovacím protokolu</strong> je nově doplněna informace o tom, kdo a kdy soupis schválil.</li></ul>',14)])])}const p=e(l,[["render",t]]);export{m as __pageData,p as default};
